from __future__ import annotations

from typing import Any, Optional

from .types import InternalRuleDef, InternalRuleType


def is_rule_def_type(type: Any = None) -> bool:
    if not type:
        return False
    try:
        return InternalRuleType(type) in InternalRuleType
    except ValueError:
        return False


def is_rule_def(rule: Any = None) -> bool:
    return isinstance(rule, InternalRuleDef) and is_rule_def_type(rule.type)


def _rule_type(rule: Any) -> Any:
    """`rule.type` in JS is `undefined` for anything that isn't a rule def."""
    return getattr(rule, "type", None)


def is_rule_def_alt(rule: Optional[InternalRuleDef] = None) -> bool:
    return rule is not None and _rule_type(rule) == InternalRuleType.ALT


def is_rule_def_ref(rule: Optional[InternalRuleDef] = None) -> bool:
    return rule is not None and _rule_type(rule) == InternalRuleType.RULE_REF


def is_rule_def_end(rule: Optional[InternalRuleDef] = None) -> bool:
    return rule is not None and _rule_type(rule) == InternalRuleType.END


def is_rule_def_char(rule: Optional[InternalRuleDef] = None) -> bool:
    return rule is not None and _rule_type(rule) == InternalRuleType.CHAR


def is_rule_def_char_not(rule: Optional[InternalRuleDef] = None) -> bool:
    return rule is not None and _rule_type(rule) == InternalRuleType.CHAR_NOT


def is_rule_def_char_alt(rule: Optional[InternalRuleDef] = None) -> bool:
    return rule is not None and _rule_type(rule) == InternalRuleType.CHAR_ALT


def is_rule_def_char_rng_upper(rule: Optional[InternalRuleDef] = None) -> bool:
    return rule is not None and _rule_type(rule) == InternalRuleType.CHAR_RNG_UPPER
