        self,
        rule_name: str,
        rule_id: int,
        depth: int = 0,
    ) -> None:
        src = self.src
        rule: List[InternalRuleDef] = []
        self.parse_sequence(rule_name, rule, depth)
        while self._at(self.pos) == "|":
