// Runs the corpus through the TypeScript reference implementation and prints one
// JSON result per case to stdout. Invoked as:
//   node --experimental-transform-types run_reference.ts <reference-src-dir> <corpus.json>
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

const [referenceDir, corpusPath] = process.argv.slice(2);
const { GBNF } = await import(resolve(referenceDir, 'gbnf.ts'));

type Case = {
  name: string;
  grammar: string;
  inputs?: string[];
  code_point_inputs?: (number | number[])[];
  steps?: string[];
};

const describeError = (e: any) => ({
  ok: false,
  error: e?.constructor?.name ?? 'Error',
  message: e?.message ?? String(e),
});

const describeState = (state: any) => ({
  ok: true,
  rules: [...state],
  size: state.size,
  grammar: state.grammar,
  graph: state._graph.print({ pointers: state._pointers, colors: false }),
  graphColored: state._graph.print({ pointers: state._pointers, colors: true }),
});

const corpus: Case[] = JSON.parse(readFileSync(corpusPath, 'utf8'));
const results: any[] = [];

for (const testCase of corpus) {
  const entry: any = { name: testCase.name };

  if (testCase.inputs !== undefined) {
    entry.inputs = testCase.inputs.map((input) => {
      try {
        return describeState(GBNF(testCase.grammar, input));
      } catch (e) {
        return describeError(e);
      }
    });
  }

  if (testCase.code_point_inputs !== undefined) {
    entry.code_point_inputs = testCase.code_point_inputs.map((input) => {
      try {
        return describeState(GBNF(testCase.grammar, input));
      } catch (e) {
        return describeError(e);
      }
    });
  }

  if (testCase.steps !== undefined) {
    const stepResults: any[] = [];
    try {
      let state = GBNF(testCase.grammar);
      stepResults.push(describeState(state));
      for (const step of testCase.steps) {
        try {
          state = state.add(step);
          stepResults.push(describeState(state));
        } catch (e) {
          stepResults.push(describeError(e));
          break;
        }
      }
    } catch (e) {
      stepResults.push(describeError(e));
    }
    entry.steps = stepResults;
  }

  results.push(entry);
}

console.log(JSON.stringify(results, null, 2));
"""Regenerate the golden files by running the TypeScript reference implementation.

    python3 tests/differential/generate_golden.py

Requires Node >= 22.6 (for `--experimental-transform-types`). The goldens are
checked in so that `tests/test_differential.py` can verify the port against the
reference's answers even where Node isn't available.
"""

from __future__ import annotations

import json
import subprocess
import sys
import tempfile
from pathlib import Path
from typing import Any, Dict, List

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from differential.setup_reference import prepare  # noqa: E402
from fuzz_cases import build_cases  # noqa: E402

TESTS_DIR = Path(__file__).resolve().parents[1]
GOLDEN_DIR = TESTS_DIR / "golden"
RUNNER = Path(__file__).resolve().parent / "run_reference.ts"


def run_reference(corpus: List[Dict[str, Any]], reference_dir: Path) -> List[Dict[str, Any]]:
    with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False) as handle:
        json.dump(corpus, handle)
        corpus_path = handle.name
    result = subprocess.run(
        [
            "node",
            "--experimental-transform-types",
            "--disable-warning=ExperimentalWarning",
            str(RUNNER),
            str(reference_dir),
            corpus_path,
        ],
        capture_output=True,
        text=True,
    )
    if result.returncode != 0:
        raise RuntimeError(f"reference runner failed:\n{result.stderr}")
    return json.loads(result.stdout)


def strip_graphs(results: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Drop the (large) rendered-graph fields; the main corpus already covers them."""
    for case in results:
        for key in ("inputs", "code_point_inputs", "steps"):
            for entry in case.get(key, []):
                entry.pop("graph", None)
                entry.pop("graphColored", None)
    return results


def main() -> None:

